actions.script:
ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").list().each {
    it.set("enabled", "N").store()
}
def existing = ec.entity.find("moqui.adk.AdkAgentConfig").condition("agentName", agentName).one()
if (existing) {
    existing.set("modelName", modelName).set("apiKey", apiKey)
        .set("instruction", instruction).set("description", description)
        .set("enabled", "Y").store()
} else {
    ec.entity.makeValue("moqui.adk.AdkAgentConfig")
        .setSequencedIdPrimary()
        .set("agentName",   agentName   ?: "MoquiAgent")
        .set("modelName",   modelName   ?: "gemini-2.0-flash")
        .set("apiKey",      apiKey)
        .set("instruction", instruction ?: "You are a helpful assistant for the GrowERP ERP system.")
        .set("description", description ?: "ADK Agent")
        .set("enabled", "Y")
        .create()
}
org.moqui.adk.AdkAgentManager.reset()

import org.moqui.adk.AdkAgentManager
boolean wasDisabled = ec.artifactExecution.disableAuthz()
try {
    def cfg = ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").one()
    def manager = AdkAgentManager.getInstance(
        cfg?.agentName   ?: "MoquiAgent",
        cfg?.modelName   ?: "gemini-2.0-flash",
        cfg?.apiKey      ?: "",
        cfg?.instruction ?: "You are a helpful assistant for the GrowERP ERP system."
    )
    sessionId = manager.createSession(ec.user.userId ?: "anonymous")
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

import org.moqui.adk.AdkAgentManager
boolean wasDisabled = ec.artifactExecution.disableAuthz()
try {
    def cfg = ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").one()
    def manager = AdkAgentManager.getInstance(
        cfg?.agentName   ?: "MoquiAgent",
        cfg?.modelName   ?: "gemini-2.0-flash",
        cfg?.apiKey      ?: "",
        cfg?.instruction ?: "You are a helpful assistant for the GrowERP ERP system."
    )
    response = manager.runSync(ec.user.userId ?: "anonymous", sessionId, message)
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
